        "identifier": "section_HWWiBL88vl2LWGfKqEqsZ",
        "name": "=✍🏻Edit custom toggles 👇==============",
        "content": "{{//Keep toggled off}}{{trim}}",
        "role": "system",
        "enabled": "false",
        "isMarker": "false",
        "groupId": "yrtlIj5jBYHAdIn2BfA64",
